from sys import version_info
from typing import TYPE_CHECKING

if version_info < (3, 11):
    from typing_extensions import assert_type
else:
    from typing import assert_type  # type:ignore[attr-defined,no-redef]


from beset import (
    Closed,
    ClosedOpen,
    ClosedOpenSet,
    ClosedSet,
    Empty,
    Interval,
    IntervalSet,
    LeftClosed,
    LeftOpen,
    Open,
    OpenClosed,
    OpenClosedSet,
    OpenSet,
    RightClosed,
    RightOpen,
    Unbounded,
)

if TYPE_CHECKING:

    def test_union(
        interval_set_int: IntervalSet[int],
        interval_set_optional: IntervalSet[int | None],
        open_set_int: OpenSet[int],
        open_set_optional: OpenSet[int | None],
        closed_set_int: ClosedSet[int],
        closed_set_optional: ClosedSet[int | None],
        open_closed_set_int: OpenClosedSet[int],
        open_closed_set_optional: OpenClosedSet[int | None],
        closed_open_set_int: ClosedOpenSet[int],
        closed_open_set_optional: ClosedOpenSet[int | None],
        interval_int: Interval[int],
        interval_optional: Interval[int | None],
        open_int: Open[int],
        open_optional: Open[int | None],
        closed_int: Closed[int],
        closed_optional: Closed[int | None],
        open_closed_int: OpenClosed[int],
        open_closed_optional: OpenClosed[int | None],
        closed_open_int: ClosedOpen[int],
        closed_open_optional: ClosedOpen[int | None],
        left_open: LeftOpen[int],
        left_closed: LeftClosed[int],
        right_open: RightOpen[int],
        right_closed: RightClosed[int],
        unbounded: Unbounded,
        empty: Empty,
    ) -> None:
        # IntervalSet[int]
        assert_type(interval_set_int.union(interval_set_int), IntervalSet[int])
        assert_type(interval_set_int.union(interval_set_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(open_set_int), IntervalSet[int])
        assert_type(interval_set_int.union(open_set_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(closed_set_int), IntervalSet[int])
        assert_type(interval_set_int.union(closed_set_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(open_closed_set_int), IntervalSet[int])
        assert_type(interval_set_int.union(open_closed_set_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(closed_open_set_int), IntervalSet[int])
        assert_type(interval_set_int.union(closed_open_set_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(interval_int), IntervalSet[int])
        assert_type(interval_set_int.union(interval_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(open_int), IntervalSet[int])
        assert_type(interval_set_int.union(open_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(closed_int), IntervalSet[int])
        assert_type(interval_set_int.union(closed_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(open_closed_int), IntervalSet[int])
        assert_type(interval_set_int.union(open_closed_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(closed_open_int), IntervalSet[int])
        assert_type(interval_set_int.union(closed_open_optional), IntervalSet[int | None])
        assert_type(interval_set_int.union(left_open), IntervalSet[int | None])
        assert_type(interval_set_int.union(left_closed), IntervalSet[int | None])
        assert_type(interval_set_int.union(right_open), IntervalSet[int | None])
        assert_type(interval_set_int.union(right_closed), IntervalSet[int | None])
        assert_type(interval_set_int.union(unbounded), Unbounded)
        assert_type(interval_set_int.union(empty), IntervalSet[int])

        # IntervalSet[int | None]
        assert_type(interval_set_optional.union(interval_set_int), IntervalSet[int | None])
        assert_type(interval_set_optional.union(interval_set_optional), IntervalSet[int | None])
        assert_type(interval_set_optional.union(open_set_int), IntervalSet[int | None])
        assert_type(interval_set_optional.union(open_set_optional), IntervalSet[int | None])
