        assert_type(interval_set_optional.union(left_open), IntervalSet[int | None])
        assert_type(interval_set_optional.union(left_closed), IntervalSet[int | None])
        assert_type(interval_set_optional.union(right_open), IntervalSet[int | None])
        assert_type(interval_set_optional.union(right_closed), IntervalSet[int | None])
        assert_type(interval_set_optional.union(unbounded), Unbounded)
        assert_type(interval_set_optional.union(empty), IntervalSet[int | None])

        # OpenSet[int]
        assert_type(open_set_int.union(interval_set_int), IntervalSet[int])
        assert_type(open_set_int.union(interval_set_optional), IntervalSet[int | None])
