    def test_intersection(
        interval_set_int: IntervalSet[int],
        interval_set_optional: IntervalSet[int | None],
        open_set_int: OpenSet[int],
        open_set_optional: OpenSet[int | None],
        closed_set_int: ClosedSet[int],
        closed_set_optional: ClosedSet[int | None],
        open_closed_set_int: OpenClosedSet[int],
        open_closed_set_optional: OpenClosedSet[int | None],
        closed_open_set_int: ClosedOpenSet[int],
        closed_open_set_optional: ClosedOpenSet[int | None],
        interval_int: Interval[int],
        interval_optional: Interval[int | None],
        open_int: Open[int],
        open_optional: Open[int | None],
        closed_int: Closed[int],
        closed_optional: Closed[int | None],
        open_closed_int: OpenClosed[int],
        open_closed_optional: OpenClosed[int | None],
        closed_open_int: ClosedOpen[int],
        closed_open_optional: ClosedOpen[int | None],
        left_open: LeftOpen[int],
        left_closed: LeftClosed[int],
        right_open: RightOpen[int],
        right_closed: RightClosed[int],
        unbounded: Unbounded,
        empty: Empty,
    ) -> None:
        # IntervalSet[int]
        assert_type(interval_set_int.intersection(interval_set_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(interval_set_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_set_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_set_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_set_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_set_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_closed_set_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_closed_set_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_open_set_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_open_set_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(interval_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(interval_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_closed_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(open_closed_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_open_int), IntervalSet[int])
        assert_type(interval_set_int.intersection(closed_open_optional), IntervalSet[int])
        assert_type(interval_set_int.intersection(left_open), IntervalSet[int])
        assert_type(interval_set_int.intersection(left_closed), IntervalSet[int])
        assert_type(interval_set_int.intersection(right_open), IntervalSet[int])
        assert_type(interval_set_int.intersection(right_closed), IntervalSet[int])
        assert_type(interval_set_int.intersection(unbounded), IntervalSet[int])
        assert_type(interval_set_int.intersection(empty), Empty)

        # IntervalSet[int | None]
        assert_type(interval_set_optional.intersection(interval_set_int), IntervalSet[int])
        assert_type(interval_set_optional.intersection(interval_set_optional), IntervalSet[int | None])
        assert_type(interval_set_optional.intersection(open_set_int), IntervalSet[int])
        assert_type(interval_set_optional.intersection(open_set_optional), IntervalSet[int | None])
        assert_type(interval_set_optional.intersection(closed_set_int), IntervalSet[int])
