        assert_type(interval_set_optional.intersection(right_open), IntervalSet[int | None])
        assert_type(interval_set_optional.intersection(right_closed), IntervalSet[int | None])
        assert_type(interval_set_optional.intersection(unbounded), IntervalSet[int | None])
        assert_type(interval_set_optional.intersection(empty), Empty)

        # OpenSet[int]
        assert_type(open_set_int.intersection(interval_set_int), IntervalSet[int])
