        assert_type(open_set_int.intersection(right_closed), IntervalSet[int])
        assert_type(open_set_int.intersection(unbounded), OpenSet[int])
        assert_type(open_set_int.intersection(empty), Empty)

        # OpenSet[int | None]
        assert_type(open_set_optional.intersection(interval_set_int), IntervalSet[int])
