        assert_type(unbounded & left_closed, LeftClosed[int])
        assert_type(unbounded & right_open, RightOpen[int])
        assert_type(unbounded & right_closed, RightClosed[int])
        assert_type(unbounded & unbounded, Unbounded)
        assert_type(unbounded & empty, Empty)

        # Empty
