        assert_type(empty & interval_set_optional, Empty)
        assert_type(empty & open_set_int, Empty)
        assert_type(empty & open_set_optional, Empty)
        assert_type(empty & closed_set_int, Empty)
        assert_type(empty & closed_set_optional, Empty)
        assert_type(empty & open_closed_set_int, Empty)
