    def test_complement(
        interval_set_int: IntervalSet[int],
        interval_set_optional: IntervalSet[int | None],
        open_set_int: OpenSet[int],
        open_set_optional: OpenSet[int | None],
        closed_set_int: ClosedSet[int],
        closed_set_optional: ClosedSet[int | None],
        open_closed_set_int: OpenClosedSet[int],
        open_closed_set_optional: OpenClosedSet[int | None],
        closed_open_set_int: ClosedOpenSet[int],
        closed_open_set_optional: ClosedOpenSet[int | None],
        interval_int: Interval[int],
        interval_optional: Interval[int | None],
        open_int: Open[int],
        open_optional: Open[int | None],
        closed_int: Closed[int],
        closed_optional: Closed[int | None],
        open_closed_int: OpenClosed[int],
        open_closed_optional: OpenClosed[int | None],
        closed_open_int: ClosedOpen[int],
        closed_open_optional: ClosedOpen[int | None],
        left_open: LeftOpen[int],
        left_closed: LeftClosed[int],
        right_open: RightOpen[int],
        right_closed: RightClosed[int],
        unbounded: Unbounded,
        empty: Empty,
    ) -> None:
        assert_type(interval_set_int.complement(), IntervalSet[int | None])
        assert_type(interval_set_optional.complement(), IntervalSet[int | None])
        assert_type(open_set_int.complement(), ClosedSet[int | None])
        assert_type(open_set_optional.complement(), ClosedSet[int | None])
        assert_type(closed_set_int.complement(), OpenSet[int | None])
        assert_type(closed_set_optional.complement(), OpenSet[int | None])
        assert_type(open_closed_set_int.complement(), OpenClosedSet[int | None])
        assert_type(open_closed_set_optional.complement(), OpenClosedSet[int | None])
        assert_type(closed_open_set_int.complement(), ClosedOpenSet[int | None])
        assert_type(closed_open_set_optional.complement(), ClosedOpenSet[int | None])
        assert_type(
            interval_int.complement(),
            OpenSet[int | None] | ClosedSet[int | None] | OpenClosedSet[int | None] | ClosedOpenSet[int | None],
        )
        assert_type(
            interval_optional.complement(),
            OpenSet[int | None] | ClosedSet[int | None] | OpenClosedSet[int | None] | ClosedOpenSet[int | None],
        )
        assert_type(open_int.complement(), ClosedSet[int | None])
        assert_type(open_optional.complement(), ClosedSet[int | None])
        assert_type(closed_int.complement(), OpenSet[int | None])
        assert_type(closed_optional.complement(), OpenSet[int | None])
        assert_type(open_closed_int.complement(), OpenClosedSet[int | None])
        assert_type(open_closed_optional.complement(), OpenClosedSet[int | None])
        assert_type(closed_open_int.complement(), ClosedOpenSet[int | None])
        assert_type(closed_open_optional.complement(), ClosedOpenSet[int | None])
        assert_type(left_open.complement(), RightClosed[int])
        assert_type(left_closed.complement(), RightOpen[int])
        assert_type(right_open.complement(), LeftClosed[int])
        assert_type(right_closed.complement(), LeftOpen[int])
        assert_type(unbounded.complement(), Empty)
        assert_type(empty.complement(), Unbounded)

    def test_invert(
        interval_set_int: IntervalSet[int],
        interval_set_optional: IntervalSet[int | None],
        open_set_int: OpenSet[int],
        open_set_optional: OpenSet[int | None],
        closed_set_int: ClosedSet[int],
        closed_set_optional: ClosedSet[int | None],
        open_closed_set_int: OpenClosedSet[int],
        open_closed_set_optional: OpenClosedSet[int | None],
        closed_open_set_int: ClosedOpenSet[int],
        closed_open_set_optional: ClosedOpenSet[int | None],
        interval_int: Interval[int],
        interval_optional: Interval[int | None],
        open_int: Open[int],
        open_optional: Open[int | None],
        closed_int: Closed[int],
        closed_optional: Closed[int | None],
        open_closed_int: OpenClosed[int],
        open_closed_optional: OpenClosed[int | None],
        closed_open_int: ClosedOpen[int],
        closed_open_optional: ClosedOpen[int | None],
        left_open: LeftOpen[int],
        left_closed: LeftClosed[int],
        right_open: RightOpen[int],
        right_closed: RightClosed[int],
        unbounded: Unbounded,
        empty: Empty,
    ) -> None:
        assert_type(~interval_set_int, IntervalSet[int | None])
        assert_type(~interval_set_optional, IntervalSet[int | None])
        assert_type(~open_set_int, ClosedSet[int | None])
        assert_type(~open_set_optional, ClosedSet[int | None])
        assert_type(~closed_set_int, OpenSet[int | None])
        assert_type(~closed_set_optional, OpenSet[int | None])
        assert_type(~open_closed_set_int, OpenClosedSet[int | None])
        assert_type(~open_closed_set_optional, OpenClosedSet[int | None])
        assert_type(~closed_open_set_int, ClosedOpenSet[int | None])
        assert_type(~closed_open_set_optional, ClosedOpenSet[int | None])
        assert_type(
            ~interval_int,
            OpenSet[int | None] | ClosedSet[int | None] | OpenClosedSet[int | None] | ClosedOpenSet[int | None],
        )
        assert_type(
            ~interval_optional,
            OpenSet[int | None] | ClosedSet[int | None] | OpenClosedSet[int | None] | ClosedOpenSet[int | None],
        )
        assert_type(~open_int, ClosedSet[int | None])
        assert_type(~open_optional, ClosedSet[int | None])
        assert_type(~closed_int, OpenSet[int | None])
        assert_type(~closed_optional, OpenSet[int | None])
        assert_type(~open_closed_int, OpenClosedSet[int | None])
        assert_type(~open_closed_optional, OpenClosedSet[int | None])
        assert_type(~closed_open_int, ClosedOpenSet[int | None])
        assert_type(~closed_open_optional, ClosedOpenSet[int | None])
        assert_type(~left_open, RightClosed[int])
        assert_type(~left_closed, RightOpen[int])
        assert_type(~right_open, LeftClosed[int])
        assert_type(~right_closed, LeftOpen[int])
        assert_type(~unbounded, Empty)
        assert_type(~empty, Unbounded)
